import pathlib,json,csv,itertools,collections
P=pathlib.Path(__file__).resolve().parents[1];OLD=P.parent/'source-test-deep-review';load=lambda p:[json.loads(x) for x in p.read_text().splitlines()]
rows=load(P/'named-identifier-pairs.jsonl')
# Authored cluster policy applied deterministically; representative reasoning is separate from pair-by-pair investigation.
def assess(a,b,shared):
 pair={a,b}
 if pair=={7,8}:return 'entity_crosswalk','support_only','ABR ABN/ACN can corroborate ASIC incorporation identity; no new consequential observation follows merely from both entries.','Verify legal form and effective status; ABN is not ACN.'
 if pair=={12,13}:return 'entity_crosswalk','support_only','NZBN bridges a business to its registry identity, but duplicated identity records are not an investigative hypothesis.','Branch/trader/company distinctions and update timing defeat simple inconsistency claims.'
 if pair=={24,28}:return 'sanctions_policy','policy_context','Same vessel on US and Canadian lists can expose regime differences, not a failure to enforce one country’s law in another.','Compare exact measures/dates and jurisdiction before proposing an implementation test.'
 if 49 in pair:return 'breach_domain','reject_control_inference','A breach email/domain hit plus registration, certificate or scanned service cannot establish organizational compromise or current employment.','Historic reuse, third-party breach and domain reassignment; no personal-email queries performed.'
 if pair=={54,55}:return 'procurement_lifecycle','specialize_reconciliation','UEI matches recipient identity, not an award/action. SAM and USAspending may share upstream contract records, so discrepancy is propagation/reconciliation first.','Obtain agency-scoped award/action keys, modifications and update dates; no independent corroboration claim.'
 if pair<={249,250,251}:return 'research_outputs','new_formulation' if pair=={249,250} else 'support_only','Crossref dated retraction notice plus OpenAlex citation graph can locate later affirmative reliance on withdrawn evidence; ORCID pairs only help author identity.','Full citing text, publication/retraction chronology and shared Retraction Watch provenance must be checked; citation may criticize the paper.'
 if 'IMO' in shared:
  if pair=={74,75}:return 'vessel_safety','new_formulation','Dated Paris/Tokyo inspections can test whether the same material deficiency recurs after a documented rectification on the same ship.','Different defect/component, lawful repair-port exception, changed owner or documentation error; permissions and reports required.'
  if pair=={71,257}:return 'vessel_measurement','duplicate_or_validation','GFW and MarineCadastre tracks may share AIS broadcasts; their agreement is not independent proof of fishing or trade.','Resolve IMO/MMSI assignment dates, coverage, interpolation and model-versus-raw observations.'
  if 257 in pair or 71 in pair:return 'vessel_event_role','specialize_existing_transport','Movement/event chronology can contextualize inspection or owner history after a typed ship-ID match; AIS alone cannot establish cargo, fishing or unlawful departure.','Check actual inspection action/exception, observation source, flag and historic ownership; retain as existing transport/safety evidence path.'
  return 'vessel_registry_inspection','support_safety','Registry/inspection linkage can identify the owner/operator responsible for answering a safety question, but company IMO must not join ship IMO.','Historical role, report details and repeated common deficiencies are more informative than mere coappearance.'
 if 'domain' in shared:return 'domain_service','specialize_existing_D03','Service/certificate/domain observations may resolve a control-change question, but TLS certificate issuance does not prove domain ownership or compromise.','Shared hosting, wildcard certificates, delegated service and stale scans; no active scanning.'
 if 151 in pair:return 'network_registry','support_only','ASN must come from the relevant number-resource registration response, not a domain RDAP object; catalog fields conflate routes.','Select ASN registry, effective assignment and observation interval before linking any outage.'
 if 146 in pair:return 'censorship_outage_discrimination','new_formulation','OONI web-connectivity anomalies can be tested against same-network reachability to distinguish selective interference from a general outage.','Different probe geography/time or inadequate measurements; negative network signal does not prove deliberate censorship.'
 if pair=={147,258}:return 'network_identity','support_only','RIPE registration and PeeringDB participation describe different network roles; disagreement can be stale volunteer or historical data.','Check actual historical organization and facility participation; no outage or ownership conclusion from names alone.'
 return 'network_observation','specialize_existing_D02','Cross-sensor ASN event comparison can characterize outage versus routing/traffic changes without multiplying each sensor pair into a new hypothesis.','Collector/probe/customer changes, observation geography and BGP reachability versus user service must be distinguished.'
for r in rows:
 a,b=int(r['source_a'][-4:]),int(r['source_b'][-4:]);cluster,decision,reason,stop=assess(a,b,r['shared_catalog_namespaces']);r.update(cluster=cluster,assessment=decision if not r['in_rule_ab'] and not r['in_rule_ba'] else 'already_in_mechanism_rules',reasoning=reason,discriminating_check=stop,review_depth='deterministic assignment to explicitly authored cluster assessment; not individually executed')
(P/'named-identifier-assessment.jsonl').write_text(''.join(json.dumps(r)+'\n' for r in rows))
with (P/'named-identifier-assessment.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
clusters=[
('research_retraction', [249],[250],(249,250),'Dated retraction → later citing paper → affirmative reliance in full text.','new','Shared Retraction Watch status is not independent corroboration; graph includes neutral/critical citations.'),
('vessel_rectification',[74],[75],(74,75),'Verified rectification of a specific serious defect → later same defect on the same vessel.','new','Need original deficiency reports, exact equipment and permission; recurrence does not automatically prove failed repair.'),
('selective_network_interference',[146],[259,260,261,262],(146,260),'Specific destination failure while broader same-ASN reachability persists can discriminate censorship from an outage.','new','Proxy geography, anomaly false positives and selective platform reachability require matched controls.'),
('shipping_protected_areas',[71,257],[229],(71,229),'Verified fishing-like activity inside an effective no-fishing area can prioritize actual activity/rule verification.','new','AIS movement is not fishing; protected designation does not itself prohibit fishing; permitted exceptions matter.'),
('environmental_public_claims',[38,219,220],[5,6,22,288],(38,5),'An issuer’s precise assertion of no specified facility violations can be compared to a final finding in the same scope.','new','Subsidiary, materiality, reporting period, appealed finding or disclosed qualification may explain apparent contradiction.'),
('procurement_propagation',[54,55],[67],(54,55),'Same award/action in multiple federal presentations may reveal outdated or double-counted reporting.','specialize_prior','UEI is recipient key only; shared upstream records and accounting stages make mismatch a data-quality question first.'),
('grant_publication_trace',[245,246],[249,250],(246,249),'A specific grant-linked output can be compared with the promised deliverable in the original funded scope.','specialize_prior_H01','Acknowledgement coverage incomplete; OpenAlex award fields documented but no sample or reporting duty established.'),
('arms_approval_delivery',[82,83],[84,85,87],(84,82),'Proposed sale and later transfer should be treated as separate lifecycle events, useful for public-claim checks.','defer','No contract/item bridge: recipient/year/category totals cannot establish approved quantities actually delivered.'),
('facility_reporting_crosswalk',[38],[217,218],(38,218),'Resolve FRS/program facility identity before comparing permits, reported releases or enforcement statements.','support','Facility keys/program scopes differ and pollutant release is not a permit exceedance without limits and measurement basis.'),
('legislative_versions',[122,124,274],[125,127,275],(124,125),'Exact bill/procedure and operative text can check an enacted-policy claim.','already_specialized_N04','Cross-jurisdiction combinations fail; enactment, commencement and implementation are distinct.'),
('satellite_object_identity',[79,80],[81],(79,81),'Full object designator can connect catalog and registration evidence.','already_specialized_R15','Shared orbital observations and registration coverage prevent an independent missing-registration allegation.'),
('weather_confounders',[188,189,202,204],[115,185,186,212],(188,115),'Rainfall or local weather can test alternative explanations for water/air anomalies.','support_existing_C07_C10','Different spatial/temporal support; reanalysis is not independently measured facility conditions.')]
M=json.loads((OLD/'mechanisms.json').read_text());rp={(a,b) for m in M for a,b in itertools.product(m['a'],m['b'])};out=[];edge=[]
for name,aa,bb,rep,idea,decision,stop in clusters:
 pairs={(a,b) for a,b in itertools.product(aa,bb) if a!=b};uncovered=[(a,b) for a,b in pairs if (a,b) not in rp and (b,a) not in rp]
 out.append(dict(cluster=name,source_role_a=aa,source_role_b=bb,representative_pair=rep,enumerated_pairs=len(pairs),outside_rules_either_direction=len(uncovered),reasoning=idea,decision=decision,falsifier=stop,scope='purpose-selected event/role cluster; not all catalog pairs'))
 for a,b in sorted(pairs):edge.append(dict(cluster=name,source_a=f'SYS-{a:04d}',source_b=f'SYS-{b:04d}',outside_rules_either_direction=(a,b) in uncovered,is_representative=(a,b)==rep,review_depth='representative reasoning only' if (a,b)==rep else 'enumerated alternative; not individually reviewed',inheritance_caution=stop))
for name,rs in [('event-role-clusters',out),('event-role-pairs',edge)]:
 (P/(name+'.jsonl')).write_text(''.join(json.dumps(r)+'\n' for r in rs))
 with (P/(name+'.csv')).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rs[0]);w.writeheader();w.writerows(rs)
summary=dict(named_namespace_unordered_pairs=len(rows),named_pairs_outside_both_rule_directions=sum(not r['in_rule_ab'] and not r['in_rule_ba'] for r in rows),event_role_clusters=len(out),event_role_cluster_pair_assignments=len(edge),event_role_distinct_ordered_pairs=len({(r['source_a'],r['source_b']) for r in edge}),representative_cluster_reviews=len(out),whole_pair_universe_individually_reviewed=False)
(P/'coverage-summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(summary)
